  list.slice(0,max).forEach(x=>{const when=isFlow(r)?(x.start>0?'after '+hours(x.start/60)+' of play':'from the start'):x.where==='before'?'before your first session':x.where==='after'?'after session '+x.session:'during session '+x.session;
   /* v7.54 : un achat d’avant qui vient d’une fiche du site est cliquable (fiche) ; sinon, aucun lien inventé. */
   if(x.type==='acquire'){const pr=p.prerequisites.find(a=>a.id===x.id||a.name===x.name),item=pr&&pr.itemId?itemFor({itemId:pr.itemId}):null;steps.push({type:'acquire',name:x.name,url:item&&item.url?item.url:undefined,detail:'−'+money(x.spend)+' · '+when+(x.minutes>0?' · '+hours(x.minutes/60)+' to get it':''),cash:x.cashAfter});}
   else if(x.type==='unlock')steps.push({type:'unlock',name:x.name,detail:['just once',x.spend?'−'+money(x.spend):'',x.receive?'+'+money(x.receive):'',when].filter(Boolean).join(' · '),cash:x.cashAfter});
   else steps.push({type:'run',name:x.name+(x.runs>1?' ×'+x.runs:''),detail:'+'+money(x.receive-x.spend)+' net · '+hours(x.minutes/60),cash:x.cashAfter});});
