 function lowText(r){const L=r&&r.lowPoint;if(!L||!Number.isFinite(L.cash)||L.cash>=r.startCash-1e-9)return '';return ' Lowest point: '+money(L.cash)+(L.at?' — '+L.at.charAt(0).toLowerCase()+L.at.slice(1):'')+(r.input.reserve>0&&L.cash>=r.input.reserve-1e-9?', never below the money set aside.':r.input.reserve===0&&L.cash<((r.keptReserve??0))?', below what you wanted to set aside.':'.');}
 function lowLine(r){const t=lowText(r);return t?'<p class="b-lowpoint">'+esc(t.trim())+'</p>':'';}
 function routeBlock(s,r){if(!(r.route||[]).some(x=>x.type==='acquire'||x.type==='unlock'))return '';return visual.chain(routeSteps(s,r),{title:'The path, in order',question:'What you buy or unlock, and when: each step opens the next.',note:'A purchase is paid only once what it requires is done and the money allows it, without touching the money set aside.'});}
 function flowNext(s,r){const first=(r.route||[]).slice(0,4);if(!first.length)return '';return '<div class="calc-next-action"><strong>To start</strong><ol class="b-next-steps">'+first.map(x=>'<li>'+(x.type==='acquire'?'Buy “'+esc(x.name)+'” <span>−'+money(x.spend)+'</span>':x.type==='unlock'?'Do “'+esc(x.name)+'” (just once) <span>'+(x.receive-x.spend>=0?'+':'−')+money(Math.abs(x.receive-x.spend))+'</span>':'“'+esc(x.name)+'” ×'+x.runs+' <span>+'+money(x.receive-x.spend)+'</span>')+'</li>').join('')+'</ol>'+btn('After playing, enter what I actually have','data-b-focus="plan-actual"')+'</div>';}
 function incompleteBlock(s){const x=analysisOf?analysisOf('plan',s):null;if(!x||!x.incomplete||!x.incomplete.length)return '';const p=s.plan;
  const steps=p.prerequisites.map(a=>({type:a.owned?'start':a.price===null?'missing':'acquire',name:a.name,detail:a.owned?'Already owned':a.price===null?'Price to come: enter the price you imagine to complete the path':money(a.price)}));steps.push({type:'goal',label:'Your goal',name:goalStep(s),detail:'Calculated as soon as the path is complete'});
  return visual.chain(steps,{title:'Path to complete',question:'An unknown price is never counted as free: enter it to get the plan.'})+'<div class="b-plan-card-actions">'+x.incomplete.map(z=>btn('Enter the price of “'+z.name+'”','data-b-focus="'+esc(z.field)+'"')).join('')+'</div>';}
 const VARIANT_KEYS=['goal','situation','source','missions','prerequisites','priority','strategy','maxRepeat','deadlineDays'];
 function variantOf(s){const p=s.plan,v={id:'v-'+Date.now().toString(36)+'-'+(p.variants||[]).length,label:(goalName(s)+' · '+(p.source==='missions'?plural(p.missions.length,'mission'):money(p.situation.hourly)+'/h')).slice(0,120),at:new Date().toISOString().slice(0,10)};VARIANT_KEYS.forEach(k=>{v[k]=B.copy(p[k]);});return v;}
 function variantState(s,v){const c=B.copy(s);VARIANT_KEYS.forEach(k=>{if(v[k]!==undefined)c.plan[k]=B.copy(v[k]);});c.plan.variant='auto';return c;}
