  doc+=section('actual','After playing: where do you really stand?',obs?'<b>'+plural(obs.sessions,'session')+(obs.sessions>1?'</b> logged with your results':'</b> logged with your result')+' · last: '+(obs.last.gain>=0?'+':'−')+money(Math.abs(obs.last.gain))+(obs.last.gap===null?'':' ('+(obs.last.gap>=0?'+':'−')+money(Math.abs(obs.last.gap))+' compared with the plan)'):'Enter what you have after your session: the whole plan recalculates','Enter what you have now and what you did. The whole plan recalculates from there: missions, purchases, sessions, days. Nothing is counted twice.',()=>actualForm(s,r,obs));
