  s.order.keys.forEach(k=>{const a=B.asset(s,k),pr=p.prerequisites.find(x=>x.id===byKey[k]);if(!a||!pr)return;pr.requires=[...new Set([...(pr.requires||[]),...(a.requires||[]).map(r=>byKey[r]).filter(Boolean)])];});
